/**
 * Text of generated files that people read (STATE.md · .saf/plan.md · session summary · report) in the
 * project's document language. CLI messages stay in English.
 */

const en = {
  stateTitle: "# Work status (generated — do not edit by hand)",
  stateNote: (c) =>
    `> Written by \`${c("task:state")}\` · \`${c("task:start")}\` · \`${c("task:verify")}\` from the files in \`docs/plan/\` · a card becomes "done" only through \`${c("task:verify", "<id>")}\` · how it works: [README.md](README.md)`,
  noActive: "No active milestone (a file in `milestones/` with `status: active`).",
  doneCount: (d, t) => `cards done ${d}/${t}`,
  doing: "In progress",
  next: "Next",
  none: "none",
  table: "| Card | Work | Status | Evidence |",
  gatesTitle: (id, cmd) => `### Exit gates of ${id} (checked with \`${cmd}\`)`,
  gatesTable: "| Gate | Criterion | Result |",
  recent: "## Latest evidence",
  nothingYet: "none yet",
  others: "## Other milestones",
  status: { legacy: "✓ done before cards", done: "✓ passed", failed: "✗ failed", in_progress: "▶ in progress", todo: "· not started" },
  gateManual: "manual check",
  gateNotRun: "not checked",
  gatePass: (t) => `✓ passed ${t}`,
  gateFail: "✗ failed",
  notStarted: "not started",
  startedNotVerified: (t) => `started ${t} · not verified yet`,
  passed: (t, n) => `passed ${t} (${n} commands)`,
  failed: (t, why) => `last check failed ${t}: ${why}`,
  whyCommands: (l) => `failed commands ${l}`,
  whyOutside: (n) => `${n} file(s) outside touch`,
  whyForbidden: (n) => `${n} file(s) in dont_touch`,
  whyScenarios: (l) => `scenarios without a test ${l}`,
  lane: (n, w) => ` · lane ${n} · ${w}`,
  nextWaiting: (l) => `no card can start yet — ${l} must pass first`,
  nextWait: (id, deps) => `${id} waits for ${deps}`,
  nextOnlyActive: "none — only cards in progress remain",
  nextGate: (cmd) => `none — all cards done, check the exit gates with ${cmd}`,
  sideHeading: (id, title) => `Side lane ${id} ${title}`,
  sideAllDone: "none — every side card is done",
  sideTag: (mid) => ` [side lane ${mid}]`,
  sessionSide: (id, d, t, doing, next) => `side lane ${id}: done ${d}/${t} · in progress ${doing} · next ${next}`,
  mirrorSide: (id) => `## Side lane (${id})`,
  mirrorHead: (cmd) => `<!-- Generated from docs/plan/ by ${cmd} — do not edit: change cards in docs/plan/tasks/ or the milestone file, then run the command -->`,
  mirrorIdle: "# Plan: no active milestone\nStatus: idle",
  mirrorSource: (file, cmd) => `Source: \`${file}\` · full status: \`docs/plan/STATE.md\` · a card becomes done only through \`${cmd}\``,
  manualSuffix: " (manual check)",
  doneBefore: (l) => ` — done before cards (${l})`,
  sessionHead: (name) => `[${name} work status — injected by the SessionStart hook from docs/plan/ · full view docs/plan/STATE.md]`,
  sessionNoActive: (owner) => `No active milestone — ask the ${owner} before starting new work.`,
  sessionMilestone: (id, title, d, t) => `milestone: ${id} ${title} · cards done ${d}/${t}`,
  sessionNoCard: "card in progress: none",
  sessionCard: (id, title, file, sum) => `card in progress: ${id} ${title} (${file}) — ${sum}`,
  sessionLaneCard: (id, title, lane, wt, br, st) => `card in progress: ${id} ${title} — lane ${lane} · worktree ${wt} · on branch ${br}: ${st}`,
  sessionCriteria: (l) => `  criteria: ${l}`,
  sessionTouch: (t, d) => `  may touch: ${t}${d ? ` · must not touch: ${d}` : ""}`,
  sessionNext: (l) => `next: ${l}`,
  sessionRecent: (l) => `latest evidence: ${l}`,
  sessionHow: (s, v) => `how to work: ${s} → do the card → ${v} (the only way a card becomes "done") → commit · .saf/plan.md and STATE.md are generated, never tick boxes by hand`,
  sessionIssues: (n, cmd) => `⚠ the plan has ${n} problem(s) — run ${cmd}`,
  laneHead: (name, lane, id, title, br) => `[${name} work status] this folder is lane ${lane} of card ${id} ${title} — a separate worktree (branch ${br}); only this card is worked on here`,
  laneStatus: (s) => `status: ${s}`,
  laneCardFile: (f) => `card: ${f}`,
  laneHow: (cmd) => `how to work: do the card → ${cmd} (repeat any time · writes evidence on this branch only) · start/abandon/other cards/state files happen in the main folder`,
  stopHead: "Cards that were started have not passed their criteria yet:",
  stopDo: (cmd) => `Keep going until \`${cmd}\` passes before reporting done.`,
  stopEnd: (owner) => `If you stop now because the ${owner} must decide something, or the work continues next round: say briefly why the card has not passed, then stop (this hook will not repeat in the same round).`,
  laneBranch: { missing: (b) => `cannot read branch (no branch ${b})`, broken: (f) => `cannot read branch (evidence ${f} missing or broken)`, done: "passed in its worktree, waiting for merge", failed: (n) => `failed check #${n}`, doing: "in progress" },
  report: {
    title: (id, t) => `# Report ${id} — ${t}`,
    note: (cmd) => `> Generated by \`${cmd}\` from the files in \`docs/plan/\` — do not edit by hand · missing data is written as "none yet"`,
    cards: "## Cards",
    cardsTable: "| Card | Work | Status | Passed at | Checks |",
    doneLine: (d, t) => `done ${d}/${t}`,
    gates: "## Exit gates",
    gatesChecked: (t, h) => `last checked ${t} (commit ${h})`,
    gatesNot: (cmd) => `not checked yet — \`${cmd}\``,
    matrix: "## Scenario ↔ test matrix (specs referenced by this milestone's cards)",
    noSpecs: (id) => `none yet — cards of ${id} reference no spec in docs/specs/`,
    matrixTable: "| Spec | Scenarios | With test | Missing |",
    raw: "Raw evidence:",
  },
};

